-- credit_balance (expected 0 mismatches)
WITH entries AS (SELECT user_id,delta FROM user_credit_ledger_000 UNION ALL SELECT user_id,delta FROM user_credit_ledger_001 UNION ALL SELECT user_id,delta FROM user_credit_ledger_002 UNION ALL SELECT user_id,delta FROM user_credit_ledger_003), changes AS (SELECT user_id,SUM(delta) delta FROM entries GROUP BY user_id) SELECT COUNT(*) FROM user_credit_account a LEFT JOIN changes c ON a.user_id=c.user_id WHERE a.balance<>a.opening_balance+COALESCE(c.delta,0);

-- quota_total (expected 0 mismatches)
WITH entries AS (SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_000 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_001 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_002 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_003), changes AS (SELECT user_id,activity_id,SUM(delta) delta FROM entries WHERE bucket_type='TOTAL' GROUP BY user_id,activity_id) SELECT COUNT(*) FROM raffle_activity_account a LEFT JOIN changes c ON a.user_id=c.user_id AND a.activity_id=c.activity_id WHERE a.total_remaining<>a.opening_total+COALESCE(c.delta,0);

-- quota_day (expected 0 mismatches)
WITH entries AS (SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_000 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_001 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_002 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_003), changes AS (SELECT user_id,activity_id,bucket_key,SUM(delta) delta FROM entries WHERE bucket_type='DAY' GROUP BY user_id,activity_id,bucket_key) SELECT COUNT(*) FROM raffle_activity_account_day a LEFT JOIN changes c ON a.user_id=c.user_id AND a.activity_id=c.activity_id AND CAST(a.business_date AS CHAR)=c.bucket_key WHERE a.remaining<>a.opening_quota+COALESCE(c.delta,0);

-- quota_month (expected 0 mismatches)
WITH entries AS (SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_000 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_001 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_002 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_003), changes AS (SELECT user_id,activity_id,bucket_key,SUM(delta) delta FROM entries WHERE bucket_type='MONTH' GROUP BY user_id,activity_id,bucket_key) SELECT COUNT(*) FROM raffle_activity_account_month a LEFT JOIN changes c ON a.user_id=c.user_id AND a.activity_id=c.activity_id AND a.business_month=c.bucket_key WHERE a.remaining<>a.opening_quota+COALESCE(c.delta,0);

-- quota_limits (expected 0 mismatches)
WITH entries AS (SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_000 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_001 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_002 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_003), changes AS (SELECT user_id,activity_id,SUM(CASE WHEN bucket_type='DAY' THEN limit_delta ELSE 0 END) day_delta,SUM(CASE WHEN bucket_type='MONTH' THEN limit_delta ELSE 0 END) month_delta FROM entries GROUP BY user_id,activity_id) SELECT COUNT(*) FROM raffle_activity_account a LEFT JOIN changes c ON a.user_id=c.user_id AND a.activity_id=c.activity_id WHERE a.day_limit<>a.opening_day_limit+COALESCE(c.day_delta,0) OR a.month_limit<>a.opening_month_limit+COALESCE(c.month_delta,0);

-- effective_draw_count (expected 0 mismatches)
WITH entries AS (SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_000 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_001 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_002 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_003), changes AS (SELECT user_id,activity_id,-SUM(delta) count_delta FROM entries WHERE bucket_type='TOTAL' AND (biz_type LIKE 'CONSUME:%' OR biz_type LIKE 'REFUND:%') GROUP BY user_id,activity_id) SELECT COUNT(*) FROM raffle_activity_account a LEFT JOIN changes c ON a.user_id=c.user_id AND a.activity_id=c.activity_id WHERE a.effective_draw_count<>a.opening_effective_count+COALESCE(c.count_delta,0);
